32	namespace ops {
33	namespace {
34	const std::string FUSION_PASS_NAME = "DistributeBarrierFusionPass";
35	const std::string FUSED_OP_TYPE2 = "DistributeBarrier";
36	const std::string FUSED_OP_TYPE_EXTEND = "DistributeBarrierExtend";
37	constexpr size_t kBarrierTotalInputs = 3;  // x_ref, time_out, elastic_info
38	constexpr size_t kBarrierTotalOutputs = 1; // x_ref
39	constexpr size_t kBarrierRequiredInputs = 1;
40	
41	// 原型输入名（def 顺序），用于 compact 构图下按名解析本地索引
42	const std::vector<std::string> BARRIER_IR_INPUT_NAMES = {"x_ref", "time_out", "elastic_info"};
43	
44	// 运行时按 ge_compiler 版本决定注册 stage：9.0.0 之前的老 toolkit 没有 kCompatibleInherited 枚举，
45	ge::CustomPassStage GetDistributeBarrierFusionPassStage()
46	{
47	    int32_t version = 0;
48	    aclsysGetVersionNum("ge_compiler", &version);
49	    if (version >= GRAPH_FUSION_SUPPORT_VERSION) {
50	        return ge::CustomPassStage::kCompatibleInherited;
51	    }
52	    return ge::CustomPassStage::kBeforeInferShape;
53	}
54	
55	// 构建 原型槽位 -> 节点本地索引 的映射（-1 表示该输入未连接），必选输入解析失败则安全回退
56	bool BuildPortMapping(ge::GNode &barrierNode, std::array<int32_t, kBarrierTotalInputs> &mapping)
57	{
58	    for (size_t irSlot = 0; irSlot < kBarrierTotalInputs; ++irSlot) {
59	        int32_t localIdx = -1;
60	        if (barrierNode.GetInputIndexByName(ge::AscendString(BARRIER_IR_INPUT_NAMES[irSlot].c_str()), localIdx) ==
61	                ge::GRAPH_SUCCESS &&
62	            localIdx >= 0) {
63	            mapping[irSlot] = localIdx;
64	        } else {
65	            mapping[irSlot] = -1; // 未连接的可选输入
66	        }
67	    }
68	    for (size_t i = 0; i < kBarrierRequiredInputs; ++i) {
69	        if (mapping[i] < 0) {
70	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "required input %s not found on node, skip fusion.",
71	                      BARRIER_IR_INPUT_NAMES[i].c_str());
72	            return false;
73	        }
74	    }
75	    return true;
76	}
