79	ge::graphStatus DistributeBarrierFusionPass::AddAttr(ge::GNode &barrierNode, ge::GNode &fusionNode)
80	{
81	    ge::AscendString nameStr;
82	    barrierNode.GetName(nameStr);
83	    // group（必选 string）与 world_size（必选 int）在 Extend 中保持不变，原样拷贝
84	    ge::AscendString group;
85	    if (barrierNode.GetAttr(ge::AscendString("group"), group) != ge::GRAPH_SUCCESS) {
86	        OPS_LOG_E(FUSION_PASS_NAME.c_str(), "node %s: get required attr group failed.", nameStr.GetString());
87	        return ge::GRAPH_FAILED;
88	    }
89	    fusionNode.SetAttr(ge::AscendString("group"), group);
90	    int64_t worldSize = 0;
91	    if (barrierNode.GetAttr(ge::AscendString("world_size"), worldSize) != ge::GRAPH_SUCCESS) {
92	        OPS_LOG_E(FUSION_PASS_NAME.c_str(), "node %s: get required attr world_size failed.", nameStr.GetString());
93	        return ge::GRAPH_FAILED;
94	    }
95	    fusionNode.SetAttr(ge::AscendString("world_size"), worldSize);
96	    return ge::GRAPH_SUCCESS;
97	}
