99	ge::graphStatus DistributeBarrierFusionPass::CreateFusionNode(ge::Graph &graph, ge::GNode &barrierNode,
100	                                                              const ge::TensorDesc &contextDesc,
101	                                                              ge::GNode &fusionNode)
102	{
103	    ge::AscendString nameStr;
104	    barrierNode.GetName(nameStr);
105	    auto fusionOp = ge::OperatorFactory::CreateOperator(std::string(nameStr.GetString()) + "_Extend",
106	                                                        FUSED_OP_TYPE_EXTEND);
107	    if (fusionOp.IsEmpty()) {
108	        OPS_LOG_E(FUSION_PASS_NAME.c_str(), "node %s: %s op not found in factory.", nameStr.GetString(),
109	                  FUSED_OP_TYPE_EXTEND.c_str());
110	        return ge::GRAPH_FAILED;
111	    }
112	    // port 0 为新增的 context 输入
113	    fusionOp.UpdateInputDesc(0U, contextDesc);
114	    // 输入 desc 按映射拷贝：仅实际连接的槽位，Extend 落位 = 原型槽位 + 1
115	    std::array<int32_t, kBarrierTotalInputs> mapping{};
116	    if (!BuildPortMapping(barrierNode, mapping)) {
117	        return ge::GRAPH_FAILED;
118	    }
119	    for (size_t irSlot = 0; irSlot < kBarrierTotalInputs; ++irSlot) {
120	        if (mapping[irSlot] < 0) {
121	            continue;
122	        }
123	        ge::TensorDesc srcDesc;
124	        if (barrierNode.GetInputDesc(mapping[irSlot], srcDesc) != ge::GRAPH_SUCCESS) {
125	            continue;
126	        }
127	        fusionOp.UpdateInputDesc(static_cast<uint32_t>(irSlot + 1), srcDesc);
128	    }
129	    // 输出 desc 索引不变
130	    for (size_t outPort = 0; outPort < kBarrierTotalOutputs; ++outPort) {
131	        ge::TensorDesc outDesc;
132	        if (barrierNode.GetOutputDesc(static_cast<int32_t>(outPort), outDesc) == ge::GRAPH_SUCCESS) {
133	            fusionOp.UpdateOutputDesc(static_cast<uint32_t>(outPort), outDesc);
134	        }
135	    }
136	    fusionNode = graph.AddNodeByOp(fusionOp);
137	    return AddAttr(barrierNode, fusionNode);
138	}
