140	ge::graphStatus DistributeBarrierFusionPass::AddEdge(ge::Graph &graph, ge::GNode &barrierNode, ge::GNode &fusionNode,
141	                                                     ge::GNode &contextNode)
142	{
143	    // 输入边：按映射取本地锚点，连到 Extend 的 原型槽位+1
144	    std::array<int32_t, kBarrierTotalInputs> mapping{};
145	    if (!BuildPortMapping(barrierNode, mapping)) {
146	        return ge::GRAPH_FAILED;
147	    }
148	    for (size_t irSlot = 0; irSlot < kBarrierTotalInputs; ++irSlot) {
149	        if (mapping[irSlot] < 0) {
150	            continue;
151	        }
152	        auto srcPair = barrierNode.GetInDataNodesAndPortIndexs(mapping[irSlot]);
153	        if (srcPair.first == nullptr) {
154	            continue;
155	        }
156	        if (graph.AddDataEdge(*srcPair.first, srcPair.second, fusionNode, static_cast<int32_t>(irSlot) + 1) !=
157	            ge::GRAPH_SUCCESS) {
158	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "add input edge for ir slot %zu failed.", irSlot);
159	            return ge::GRAPH_FAILED;
160	        }
161	    }
162	    // context 边：Const 节点 → Extend port 0
163	    if (graph.AddDataEdge(contextNode, 0, fusionNode, 0) != ge::GRAPH_SUCCESS) {
164	        OPS_LOG_E(FUSION_PASS_NAME.c_str(), "add context edge failed.");
165	        return ge::GRAPH_FAILED;
166	    }
167	    // 迁移控制边到 Extend，否则 RemoveNode 时 IsolateNode 会把控制边旁路拼出环
168	    for (auto &inCtrlNode : barrierNode.GetInControlNodes()) {
169	        if (graph.AddControlEdge(*inCtrlNode, fusionNode) != ge::GRAPH_SUCCESS) {
170	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "migrate in-control edge failed.");
171	            return ge::GRAPH_FAILED;
172	        }
173	    }
174	    for (auto &outCtrlNode : barrierNode.GetOutControlNodes()) {
175	        if (graph.AddControlEdge(fusionNode, *outCtrlNode) != ge::GRAPH_SUCCESS) {
176	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "migrate out-control edge failed.");
177	            return ge::GRAPH_FAILED;
178	        }
179	    }
180	    // 收集输出消费者，先摘除原节点的输出数据边（避免 IsolateNode 旁路拼接出垃圾边）
181	    std::vector<std::vector<std::pair<ge::GNodePtr, int32_t>>> outputConsumers(kBarrierTotalOutputs);
182	    for (size_t i = 0; i < kBarrierTotalOutputs; ++i) {
183	        outputConsumers[i] = barrierNode.GetOutDataNodesAndPortIndexs(static_cast<int32_t>(i));
184	        for (auto &outPair : outputConsumers[i]) {
185	            if (graph.RemoveEdge(barrierNode, static_cast<int32_t>(i), *outPair.first, outPair.second) !=
186	                ge::GRAPH_SUCCESS) {
187	                OPS_LOG_E(FUSION_PASS_NAME.c_str(), "remove output edge for port %zu failed.", i);
188	                return ge::GRAPH_FAILED;
189	            }
190	        }
191	    }
192	    // 摘除原节点的控制边（src_port/dst_port 均为 -1 表示控制锚点）
193	    for (auto &inCtrlNode : barrierNode.GetInControlNodes()) {
194	        if (graph.RemoveEdge(*inCtrlNode, -1, barrierNode, -1) != ge::GRAPH_SUCCESS) {
195	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "remove in-control edge failed.");
196	            return ge::GRAPH_FAILED;
197	        }
198	    }
199	    for (auto &outCtrlNode : barrierNode.GetOutControlNodes()) {
200	        if (graph.RemoveEdge(barrierNode, -1, *outCtrlNode, -1) != ge::GRAPH_SUCCESS) {
201	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "remove out-control edge failed.");
202	            return ge::GRAPH_FAILED;
203	        }
204	    }
205	    // 删除原节点后，把输出数据边连到 Extend（输出索引不变）
206	    graph.RemoveNode(barrierNode);
207	    for (size_t i = 0; i < kBarrierTotalOutputs; ++i) {
208	        for (auto &outPair : outputConsumers[i]) {
209	            if (graph.AddDataEdge(fusionNode, static_cast<int32_t>(i), *outPair.first, outPair.second) !=
210	                ge::GRAPH_SUCCESS) {
211	                OPS_LOG_E(FUSION_PASS_NAME.c_str(), "add output edge for port %zu failed.", i);
212	                return ge::GRAPH_FAILED;
213	            }
214	        }
215	    }
216	    return ge::GRAPH_SUCCESS;
217	}
218	
219	ge::graphStatus DistributeBarrierFusionPass::FusionNode(ge::Graph &graph, ge::GNode &barrierNode,
220	                                                        ge::GNode &contextNode, const ge::TensorDesc &contextDesc)
221	{
222	    ge::GNode fusionNode;
223	    if (CreateFusionNode(graph, barrierNode, contextDesc, fusionNode) != ge::GRAPH_SUCCESS) {
224	        return ge::GRAPH_FAILED;
225	    }
226	    return AddEdge(graph, barrierNode, fusionNode, contextNode);
227	}
228	
229	ge::graphStatus DistributeBarrierFusionPass::Run(ge::GraphPtr &graph, ge::CustomPassContext &passContext)
230	{
231	    (void)passContext;
232	    if (graph == nullptr) {
233	        return ge::GRAPH_FAILED;
234	    }
235	    // 9.0.0 版本前运行降级空跑
236	    int32_t geCompilerVersion = 0;
237	    aclsysGetVersionNum("ge_compiler", &geCompilerVersion);
238	    if (geCompilerVersion < GRAPH_FUSION_SUPPORT_VERSION) {
239	        OPS_LOG_D(FUSION_PASS_NAME.c_str(), "skip when cann version not compatible.");
240	        return ge::GRAPH_SUCCESS;
241	    }
242	    // 仅 A5 支持 DistributeBarrierExtend
243	    if (!IsTargetPlatformNpuArch(FUSION_PASS_NAME.c_str(), NPUARCH_A5)) {
244	        OPS_LOG_D(FUSION_PASS_NAME.c_str(), "target platform is not A5, skip.");
245	        return ge::GRAPH_SUCCESS;
246	    }
247	    // 按 group 缓存 context Const 节点，同图同通信域的多个 barrier 节点复用
248	    std::map<std::string, ge::GNode> contextNodes;
249	    for (auto &gNode : graph->GetDirectNode()) {
250	        ge::AscendString nodeType;
251	        if ((gNode.GetType(nodeType) != ge::GRAPH_SUCCESS) || (nodeType != FUSED_OP_TYPE2.c_str())) {
252	            continue;
253	        }
254	        ge::AscendString group;
255	        if (gNode.GetAttr(ge::AscendString("group"), group) != ge::GRAPH_SUCCESS || group.GetString() == nullptr) {
256	            continue;
257	        }
258	#if HCOMM_VERSION_NUM >= HCCL_CHANNEL_SUPPORT_VERSION
259	        std::string groupStr = group.GetString();
260	        if (contextNodes.find(groupStr) == contextNodes.end()) {
261	            std::vector<int32_t> contextData;
262	            int64_t hcclBuffSize = 0;
263	            if (!ops::Mc2MoeGraphContext::GetContextData(groupStr, contextData, hcclBuffSize)) {
264	                OPS_LOG_E(FUSION_PASS_NAME.c_str(), "get mc2 context data failed, barrier node kept as-is.");
265	                continue;
266	            }
267	            // 先按名查重：D&C 的 pass 可能已为本通信域创建过 context Const
268	            ge::GNode contextNode = ops::Mc2MoeGraphContext::FindContextConstNode(*graph, groupStr);
269	            ge::AscendString tmpType;
270	            if (contextNode.GetType(tmpType) != ge::GRAPH_SUCCESS) {
271	                if (ops::Mc2MoeGraphContext::CreateContextConstNode(*graph, groupStr, contextData, contextNode) !=
272	                    ge::GRAPH_SUCCESS) {
273	                    continue;
274	                }
275	            }
276	            contextNodes.emplace(groupStr, contextNode);
277	        }
278	        ge::GNode contextNode = contextNodes[groupStr];
279	        ge::TensorDesc contextDesc;
280	        if (contextNode.GetOutputDesc(0, contextDesc) != ge::GRAPH_SUCCESS) {
281	            continue;
282	        }
283	        ge::AscendString nameStr;
284	        gNode.GetName(nameStr);
285	        if (FusionNode(*graph, gNode, contextNode, contextDesc) != ge::GRAPH_SUCCESS) {
286	            OPS_LOG_E(FUSION_PASS_NAME.c_str(), "node %s: barrier to extend fusion failed.", nameStr.GetString());
287	            continue;
288	        }
289	        OPS_LOG_I(FUSION_PASS_NAME.c_str(), "replace %s with %s success.", nameStr.GetString(),
290	                  FUSED_OP_TYPE_EXTEND.c_str());
291	#else
292	        // 老 HCCL 版本不支持 mc2 context，保持原 barrier 节点不变
293	        OPS_LOG_D(FUSION_PASS_NAME.c_str(), "hccl version not support mc2 context, barrier node kept as-is.");
294	        continue;
295	#endif
296	    }
297	    return ge::GRAPH_SUCCESS;
298	}
299	
300	REG_FUSION_PASS(DistributeBarrierFusionPass).Stage(GetDistributeBarrierFusionPassStage());
301	} // namespace ops
302	#endif // CANN_VERSION_NUM >= GRAPH_FUSION_SUPPORT_VERSION
