        context->SetOutputDataType(INDEX_3, ge::DT_BF16);
        return GRAPH_SUCCESS;
    }

    // softmax_out, outidx:2
    context->SetOutputDataType(INDEX_2, dtype);
    // attention_out, outidx:3
    context->SetOutputDataType(INDEX_3, dtype);
    return GRAPH_SUCCESS;
}

